vec4 effect(vec2 uv) {
  float t = floor(uTime * 14.0);
  vec2 o1 = (vec2(hash(vec2(t, 1.0)), hash(vec2(t, 2.0))) - 0.5) * 0.03 * uAmount;
  vec2 o2 = (vec2(hash(vec2(t, 3.0)), hash(vec2(t, 4.0))) - 0.5) * 0.03 * uAmount;
  return vec4(getColor(uv + o1).r, getColor(uv).g, getColor(uv + o2).b, getColor(uv).a);
}
